exports.call=function(operation,input){
 if(!/^https?:$/.test(window.location.protocol))return Promise.reject(Error(exports.danish($tw.wiki)?'Åbn wikien fra ForgeShare':'Open the wiki from ForgeShare'));
 return fetch('/_forgeshare/bridge/'+operation,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-ForgeShare':'1'},body:JSON.stringify(input||{})}).then(function(response){if(!response.ok){if(response.status===413)throw Error(exports.danish($tw.wiki)?'Billederne fylder for meget. Vælg et mindre screenshot.':'Images are too large. Choose a smaller screenshot.');throw Error(exports.danish($tw.wiki)?'Godkend adgang i ForgeShare → Nøgleboks, eller kontrollér forbindelsen.':'Approve access in ForgeShare → Vault, or check the connection.');}return response.json();});
};
exports.danish=function(wiki){return /(?:da-DK|huwiki-da|Dansk)/i.test(wiki.getTiddlerText('$:/language',''));};
exports.pair=function(){
 var da=exports.danish($tw.wiki),label=window.prompt(da?'Navn på denne enhed eller person':'Name this device or person');
 if(!label)return Promise.resolve();
 return exports.call('pair',{label:label}).then(function(data){window.alert((da?'Åbn Nøgleboks i ForgeShare, vælg Godkend en enhed, og kontrollér denne kode: ':'Open Vault in ForgeShare, choose Approve a device and match this code: ')+data.code);});
};

exports.rpc=function(method,arg){
 if(method==='huPrivateVaultList')return exports.call('connections');
 if(method==='huPrivateVaultAiModels')return exports.call('models',{connectionId:typeof arg==='string'?arg:arg.connectionId});
 if(method==='huPrivateVaultAiGenerate')return exports.call('generate',{connectionId:arg.connectionId,model:arg.model,messages:arg.messages,images:(arg.images||[]).map(function(im){return {mimeType:im.mimeType,data:im.data};}),consent:arg.consent===true||!!(arg.consent&&arg.consent.approved)});
 if(method==='huPrivateVaultAiGenerateImage')return Promise.reject(Error(exports.danish($tw.wiki)?'Billedgenerering gennem ForgeShare er endnu ikke implementeret. Billedanalyse er understøttet.':'Image generation through ForgeShare is not implemented yet. Image analysis is supported.'));
 return Promise.reject(Error('Denne funktion understøttes endnu ikke af ForgeShare / This operation is not yet supported by ForgeShare'));
};
